# Compute max of column 'UK Singles' grouped by 'Song'
print(f"🔧 Computing max of 'UK Singles' grouped by 'Song'")

# Check if columns exist and operation is valid
if 'UK Singles' not in df.columns:
    print(f"❌ Error: Column 'UK Singles' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Song' not in df.columns:
    print(f"❌ Error: Group by column 'Song' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "max" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'max'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "max" == "count":
            result = df.groupby('Song')['UK Singles'].count()
        elif "max" == "sum":
            result = df.groupby('Song')['UK Singles'].sum()
        elif "max" == "avg":
            result = df.groupby('Song')['UK Singles'].mean()
        elif "max" == "min":
            result = df.groupby('Song')['UK Singles'].min()
        elif "max" == "max":
            result = df.groupby('Song')['UK Singles'].max()

        print(f"✅ Max of 'UK Singles' by 'Song':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Song', f'max_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped max: {e}")
        print(f"Column dtypes: {df[['UK Singles', 'Song']].dtypes}")
